import React from 'react';
import { Typography } from 'antd';
import CalendarGrid from './components/CalendarGrid';
import FilterPanel from './components/FilterPanel';
import AvailabilityBadges from './components/AvailabilityBadges';
import useCalendarState from './hooks/useCalendarState';

const { Title } = Typography;

const NormalFlightAvailabilityCalendar = ({ flightData, currentRoute, onDateRangeSelect, selectedRange }) => {
  // Use our custom hook to manage all the state and logic
  const calendarState = useCalendarState(flightData, currentRoute, onDateRangeSelect, selectedRange);

  // Render availability badges for a specific route, classes, and date
  const renderAvailabilityBadges = (route, classes, date) => {
    return (
      <AvailabilityBadges 
        route={route}
        classes={classes}
        date={date}
        flightData={flightData}
        cellPages={calendarState.cellPages}
        getFlightsForClassWithFilters={calendarState.getFlightsForClassWithFilters}
        createEnhancedTooltip={calendarState.createEnhancedTooltip}
        activeTooltipRef={calendarState.activeTooltipRef}
      />
    );
  };

  return (
    <div className="flight-availability-calendar">
      <Title level={3}>Flight Availability Calendar</Title>

      {/* Filter panel */}
      <FilterPanel 
        // Filter states
        segmentFilter={calendarState.segmentFilter}
        setSegmentFilter={calendarState.setSegmentFilter}
        segmentSearchText={calendarState.segmentSearchText}
        setSegmentSearchText={calendarState.setSegmentSearchText}
        classFilter={calendarState.classFilter}
        setClassFilter={calendarState.setClassFilter}
        directFilter={calendarState.directFilter}
        setDirectFilter={calendarState.setDirectFilter}
        sourceFilter={calendarState.sourceFilter}
        setSourceFilter={calendarState.setSourceFilter}
        sourceSearchText={calendarState.sourceSearchText}
        setSourceSearchText={calendarState.setSourceSearchText}
        airlinesFilter={calendarState.airlinesFilter}
        setAirlinesFilter={calendarState.setAirlinesFilter}
        airlinesSearchText={calendarState.airlinesSearchText}
        setAirlinesSearchText={calendarState.setAirlinesSearchText}
        pointsFilter={calendarState.pointsFilter}
        setPointsFilter={calendarState.setPointsFilter}
        dateFilter={calendarState.dateFilter}
        setDateFilter={calendarState.setDateFilter}
        dateSearchText={calendarState.dateSearchText}
        setDateSearchText={calendarState.setDateSearchText}
        additionalFilters={calendarState.additionalFilters}
        setAdditionalFilters={calendarState.setAdditionalFilters}
        groupFilters={calendarState.groupFilters}
        setGroupFilters={calendarState.setGroupFilters}
        segmentFilters={calendarState.segmentFilters}
        setSegmentFilters={calendarState.setSegmentFilters}
        originSearchText={calendarState.originSearchText}
        setOriginSearchText={calendarState.setOriginSearchText}
        destSearchText={calendarState.destSearchText}
        setDestSearchText={calendarState.setDestSearchText}

        // Utility functions
        getUniqueSegments={calendarState.getUniqueSegments}
        getUniqueSources={calendarState.getUniqueSources}
        getUniqueAirlines={calendarState.getUniqueAirlines}
        getPointsRange={calendarState.getPointsRange}
        getUniqueDates={calendarState.getUniqueDates}
        sortSegments={calendarState.sortSegments}
        moveSegment={calendarState.moveSegment}

        // Data
        flightData={flightData}
      />

      {/* Error message if any */}
      {calendarState.error && (
        <div className="error-message">{calendarState.error}</div>
      )}

      {/* Calendar grid component */}
      <CalendarGrid 
        currentYear={calendarState.currentYear}
        currentMonth={calendarState.currentMonth}
        goToPrevMonth={calendarState.goToPrevMonth}
        goToNextMonth={calendarState.goToNextMonth}
        selectionStart={calendarState.localSelectionStart}
        selectionEnd={calendarState.localSelectionEnd}
        handleDateClick={calendarState.handleDateClick}
        handlePageChange={calendarState.handlePageChange}
        renderAvailabilityBadges={renderAvailabilityBadges}
        shouldRenderDate={calendarState.shouldRenderDate}
        currentRoute={currentRoute}
      />

      {/* Selection information */}
      {calendarState.localSelectionStart && (
        <div className="selection-info">
          <p>
            Selected: {calendarState.localSelectionStart}
            {calendarState.localSelectionEnd && ` to ${calendarState.localSelectionEnd}`}
          </p>
        </div>
      )}
    </div>
  );
};

export default NormalFlightAvailabilityCalendar;
